entries[228386] = { ["name"] = "Verrottendes Seil", ["text"] = "\"Hängt an einem Zwirnsfaden.\"\nVerkaufspreis:" }
entries[228387] = { ["name"] = "Bröckelndes Bismut", ["text"] = "\"Korrodiertes und unbrauchbares Erz.\"\nVerkaufspreis:" }
entries[228388] = { ["name"] = "Feuchte Puppe", ["text"] = "\"Von der Strömung erfasst und Euch überlassen.\"\nVerkaufspreis:" }
entries[228390] = { ["name"] = "Linker Stiefel", ["text"] = "\"Da fehlt doch was...\"\nVerkaufspreis:" }
entries[228391] = { ["name"] = "Rechter Stiefel", ["text"] = "\"Eine Hälfte des Rätsels...\"\nVerkaufspreis:" }
entries[228392] = { ["name"] = "Korrodierte Taschenuhr", ["text"] = "\"Auch eine kaputte Uhr geht zweimal am Tag richtig.\"\nVerkaufspreis:" }
entries[228393] = { ["name"] = "Zerschmetterte Laterne", ["text"] = "\"Verrostetes Metall kann die Lampe nicht mehr vor den Elementen schützen.\"\nVerkaufspreis:" }
entries[228394] = { ["name"] = "Verlorene Notiz", ["text"] = "\"Tragischerweise steht da: \"Bitte vergesst nicht...\"\"\nVerkaufspreis:" }
entries[228395] = { ["name"] = "Schlammklumpen", ["text"] = "\"Ein Klumpen von Dingen, die in, nun ja, Schlamm eingeschlossen sind.\"\nVerkaufspreis:" }
entries[228396] = { ["name"] = "Toter Fisch", ["text"] = "\"Einfachster Fang des Tages.\"\nVerkaufspreis:" }
entries[228398] = { ["name"] = "Wütender Stein", ["text"] = "Benutzen: Wirft ihn zurück ins Wasser.\n\"Legt den besser wieder dahin, wo Ihr ihn gefunden habt.\"\nVerkaufspreis:" }
entries[228399] = { ["name"] = "Trauriger Stein", ["text"] = "Benutzen: Erzählt Euren besten Witz.\n\"Lachen ist die beste Medizin.\"\nVerkaufspreis:" }
entries[228400] = { ["name"] = "Glücklicher Stein", ["text"] = "\"Er sieht glücklicher aus, und Ihr auch.\"\nVerkaufspreis:" }
entries[228407] = { ["name"] = "Sonnenfunkenkerze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert für 5 Min. eine Funkensonnenkerze, die Verbündete in der Nähe allmählich heilt.\nNur in Khaz Algar nutzbar. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[228408] = { ["name"] = "Käferkokelkerze", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Platziert für 5 Min. eine Käferkokelkerze, die Gegnern in der Nähe Schaden zufügt.\nNur in Khaz Algar nutzbar. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[228409] = { ["name"] = "Valrins süße Brötchen", ["text"] = "Questgegenstand\n\"Dieses Paket enthält mehrere von Valrins süßen Brötchen und einen neuen Satz Federkiele.\"" }
entries[228411] = { ["name"] = "Cyrces Reif", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nFinger\n+10.359 Ausdauer\n\nPlatz des singenden Donners\nPlatz der singenden See\nPlatz des singenden Windes\n\"Seebären und Geschichtenerzähler berichten von einer mythischen Sirene, die selbst die stursten Seefahrer in ihr nasses Grab locken konnte.\"" }
entries[228412] = { ["name"] = "Späherkarte: Der Himmel über den Dracheninseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Findet Flugpunkte und deckt Karten auf den Dracheninseln auf.\n\"Ein Bündel von Dokumenten, die die komplexen Windmuster beschreiben, die über den Dracheninseln kreuzen.\"" }
entries[228413] = { ["name"] = "Leuchtkäferköder", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Ruft einen Schwarm Glühwürmchen an Eure Seite. (2 Std. Abklingzeit)" }
entries[228414] = { ["name"] = "Ausgefranste Kabel", ["text"] = "Handwerksmaterial\n\"Ein beschädigtes Ingenieurskunstbauteil, das zur Herstellung anderer Komponenten verwendet werden kann. Ihr könnt es bei Ingenieurskunstlieferanten in ganz Khaz Algar kaufen.\"\nVerkaufspreis:" }
entries[228415] = { ["name"] = "Adelgonns Tagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein abgenutztes, verstaubtes Tagebuch mit einem Steineinband, der mit komplizierten geometrischen Mustern versehen ist.\"\n<Zum Lesen rechtsklicken>" }
entries[228416] = { ["name"] = "Stahladers Manifest", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein gefalteter Handzettel, handgeschrieben mit präzisen, aber fetten Buchstaben.\"\n<Zum Lesen rechtsklicken>" }
entries[228417] = { ["name"] = "Notfallgesundheitsstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt sofort 30% Gesundheit wieder her.\n\"Hastig gefertigt, aber nicht weniger mächtig.\"" }
