entries[228449] = { ["name"] = "Schmackhafter Eisenbarren", ["text"] = "\"Köstlich und reich an Eisen.\"\nVerkaufspreis:" }
entries[228450] = { ["name"] = "Essbare Kupfernuggets", ["text"] = "\"Zumindest für Irdene essbar.\"\nVerkaufspreis:" }
entries[228451] = { ["name"] = "Leckerer Goldbarren", ["text"] = "\"Gold hat einen köstlich kostbaren Geschmack.\"\nVerkaufspreis:" }
entries[228452] = { ["name"] = "Tiefste dunkelste Schwarztinte", ["text"] = "\"Lässt sich nicht gut mit anderen Farben mischen, was insbesondere auf Rosa zutrifft.\"\nVerkaufspreis:" }
entries[228453] = { ["name"] = "Extra große Tüte Popkiesel", ["text"] = "\"Wird am besten zu Glutbräumet serviert.\"\nVerkaufspreis:" }
entries[228454] = { ["name"] = "Sammlerprogrammzettel zum Gedenken des Proszeniums", ["text"] = "\"Nummer 137 von 500.\"\nVerkaufspreis:" }
entries[228455] = { ["name"] = "Felsstoffballen", ["text"] = "\"Felsstoffballen sind für die meisten Völker zu schwer zum Tragen.\"\nVerkaufspreis:" }
entries[228456] = { ["name"] = "Felsstoff", ["text"] = "\"Felsstoff ist viel für die meisten Völker viel zu schwer, um damit zu schneidern.\"\nVerkaufspreis:" }
entries[228457] = { ["name"] = "Notenbuch der Lichtfunken", ["text"] = "Wird beim Aufheben gebunden\n\"Direktor Fynchs Notizen und Bewertungen zu den Fähigkeiten der Schüler.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[228458] = { ["name"] = "Felsstofftasche", ["text"] = "\"Diese Tasche ist viel zu schwer für die meisten Völker. Wenigstens reißt sie nicht!\"\nVerkaufspreis:" }
entries[228481] = { ["name"] = "Winzige Tiefenmuschel", ["text"] = "\"Tiefenmuscheln können zwar bildhübsche schillernde Perlen enthalten, doch sie zu ernten, ist wahrhaft gefährlich. Die hier ist zu klein, um etwas von Bedeutung in sich zu tragen.\"\nVerkaufspreis:" }
entries[228482] = { ["name"] = "Gerissene schillernde Perle", ["text"] = "\"Die Risse in dieser Perle haben ihr ihren Glanz genommen.\"\nVerkaufspreis:" }
entries[228483] = { ["name"] = "Liebevoll geschnitzter Ramolith", ["text"] = "\"Von einem Künstler geschnitzte Interpretation eines Ramoliths.\"\nVerkaufspreis:" }
entries[228485] = { ["name"] = "Ersatzschnippelmesser des Schnitzers", ["text"] = "\"Dieses beschädigte Messer ist gut, um weiche Holzstöcke zu schnitzen, aber für viel mehr ist es nicht zu gebrauchen.\"\nVerkaufspreis:" }
entries[228487] = { ["name"] = "Frisch gefallene Stöcke", ["text"] = "\"Warten lediglich auf die richtigen Hände, um etwas Besonderes daraus zu machen.\"\nVerkaufspreis:" }
entries[228488] = { ["name"] = "Kleine Glasvase", ["text"] = "\"Glas- und Tonwaren der Irdenen sind für gewöhnlich quadratisch und nicht rund wie bei den meisten anderen Völkern.\"\nVerkaufspreis:" }
entries[228489] = { ["name"] = "Todschicke Flasche", ["text"] = "\"Sorgt für Gesprächsstoff, mehr nicht.\"\nVerkaufspreis:" }
entries[228490] = { ["name"] = "Frische Weidefelsen", ["text"] = "\"Diese Felsbrocken haben den Irdenen zu wenig Geschmack, doch als Ramolithenfutter sind sie perfekt geeignet.\"\nVerkaufspreis:" }
entries[228491] = { ["name"] = "Ramolithbettmaterial", ["text"] = "\"Ramolithen lieben es, darauf zu schlafen.\"\nVerkaufspreis:" }
entries[228492] = { ["name"] = "Würzige Rubine", ["text"] = "Benutzen:\n\"Rubine sind nichts für Irdene mit sanften Gaumen.\"\nVerkaufspreis:" }
entries[228493] = { ["name"] = "Saure Topazhappen", ["text"] = "Benutzen:\n\"Die Irdenen haben eine altbewährte Tradition, herauszufinden, wer am meisten davon am Stück essen kann.\"\nVerkaufspreis:" }
entries[228494] = { ["name"] = "Knackige Zuckerkiesel", ["text"] = "Benutzen:\n\"Perfekt für alle Irdenen, die Süßes lieben.\"\nVerkaufspreis:" }
entries[228495] = { ["name"] = "Stark abgenutzte Töpferscheibe", ["text"] = "\"Ohne Töpferscheibe keine Töpferware.\"\nVerkaufspreis:" }
entries[228496] = { ["name"] = "Gesprungene Laterne", ["text"] = "\"Diese Laterne kann immer noch Licht spenden, doch die Schäden machen sie zu einem Sicherheitsrisiko.\"\nVerkaufspreis:" }
entries[228497] = { ["name"] = "Verrostetes Luftschiffzahnrad", ["text"] = "\"Dieses Zahnrad ist zu verrostet, um noch irgendeinen Wert zu haben.\"\nVerkaufspreis:" }
entries[228507] = { ["name"] = "Schwärmilbeneiersack", ["text"] = "Verkaufspreis:" }
