entries[228560] = { ["name"] = "Antike Kuriosität", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nEinzigartig\n\"Ein irdenes Relikt, das Macht gewährt. Könnte es ein Geschenk der Titanen gewesen sein? Oder eine ganz eigene Erfindung?\"\nVerkaufspreis:" }
entries[228580] = { ["name"] = "Götze der brutalen Kraft", ["text"] = "Rang 1/4\nWird beim Aufheben gebunden\nBenutzen: Springt auf Brann, wenn er dazu auffordert, damit er Spielercharaktere auf ihre Gegner schleudert, was diese zurückstößt und ihnen erheblichen körperlichen Schaden zufügt, der unter ihnen aufgeteilt wird.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung." }
entries[228581] = { ["name"] = "Antike Kuriosität", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nEinzigartig\n\"Schon das Halten dieses Relikts verleiht Euch das Gefühlt, flott auf den Beinen zu sein. Etwas, das die Irdenen im Anbetracht ihrer schweren Rahmen sicherlich schätzen würden.\"\nVerkaufspreis:" }
entries[228582] = { ["name"] = "Optimiertes Relikt", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nBenutzen: Außerhalb eines Kampfes steigt die Bewegungsgeschwindigkeit der Gruppenmitglieder um 10 %. Bei Kampfeintritt steigt das Tempo der Gruppenmitglieder 8 Sek. lang um 5 %.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung.\nVerkaufspreis:" }
entries[228608] = { ["name"] = "Über die Anwendung von Arathitechnologie auf das irdene Leben", ["text"] = "\"Band zwei.\"\nVerkaufspreis:" }
entries[228609] = { ["name"] = "Felsrösten für Anfänger", ["text"] = "\"Zwanzig Rezepte, die Euren Felsen und Mineralien mehr Geschmack entlocken!\"\nVerkaufspreis:" }
entries[228614] = { ["name"] = "Trank des Rattensprachverständnisses", ["text"] = "Questgegenstand\nBenutzen: Wer es trinkt, kann garantiert mit Ratten sprechen. (6 Sek. Abklingzeit)\n\"Auf einem Schild an der Seite steht: Lässt Euch mit Ratten sprechen. Garantiert.\"" }
entries[228617] = { ["name"] = "Benatauks Hinweisheft", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Entziffert die Hinweise, sobald sie für Euch enthüllt werden, und findet heraus, wohin Ihr als Nächstes müsst!\"\n<Zum Lesen rechtsklicken>" }
