entries[228921] = { ["name"] = "Gaunahs extra starkes Verzierungspulver", ["text"] = "Optionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Gewährt Eurer hergestellten Ausrüstung eine nicht wahrnehmbare, aber garantiert echte Verbesserung.\nBenutzbar mit: Rezepte aus Khaz Algar für die meisten schmucklosen Ausrüstungsgegenstände.\n\"Lässt jegliche vorherigen Verzierungen Eurer Ausrüstung garantiert alt aussehen. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[228930] = { ["name"] = "Zierendes Band", ["text"] = "Handwerksmaterial\n\"Ein geschmeidiges Band, das von Schneidern verwendet wird, um aufwendige, mächtige Ausrüstung zu schmücken.\"\nVerkaufspreis:" }
