entries[228937] = { ["name"] = "Wasserfeste Notiz", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Ein magisches Siegel verhindert, dass diese Notiz nass wird. Riecht leicht nach Teufelsmagie.\"\n<Zum Lesen rechtsklicken>" }
entries[228938] = { ["name"] = "Seltsamer Edelstein", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nEinzigartig\n\"Mit der Wärme einer mysteriösen Kraft durchdrungen.\"" }
entries[228940] = { ["name"] = "Ruhestein des berüchtigten Faden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\nKann nur von denjenigen verwendet werden, die sich den Durchtrennten Fäden bewiesen haben.\nErfordert den Ruf 'Strippenzieher' bei der Weberin, dem General oder dem Wesir.\n\"Kehrt mit der Hilfe Eurer Patrone der Durchtrennten Fäden nach Hause zurück.\"" }
entries[228941] = { ["name"] = "Inaktiver seltsamer Schlüssel", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nBenutzen: Sockelt einen Edelstein in den Schlüssel.\n\"Ein ramponierter alter Schlüssel. Er scheint eine Fassung für etwas zu haben.\"" }
entries[228942] = { ["name"] = "Großzügiger Kasten", ["text"] = "80 ( 80)\n\"Enthält mächtige Ausrüstung, ein strahlendes Echo, zusätzliche Währungen und eine Chance auf eine neue oder aufgewertete Kuriosität. Benötigt zum Öffnen einen restaurierten Kastenschlüssel.\"" }
entries[228943] = { ["name"] = "Durchtrennter Faden des Spionagemeisters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht dem Einsatz Eures Ruhesteins des berüchtigten Fadens einen kosmetischen Hauch der Weberin.\nErfordert den Ruf 'Strippenzieher' bei der Weberin.\n\"Die Weberin entrichtet ihre besten Wünsche.\"" }
entries[228944] = { ["name"] = "Durchtrennter Faden des Gruftlords", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht dem Einsatz Eures Ruhesteins des berüchtigten Fadens einen kosmetischen Hauch des Generals.\nErfordert den Ruf 'Strippenzieher' beim General.\n\"Der General entrichtet seine höchste Anerkennung.\"" }
entries[228945] = { ["name"] = "Durchtrennter Faden des Exekutors", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht dem Einsatz Eures Ruhesteins des berüchtigten Fadens einen kosmetischen Hauch des Wesirs.\nErfordert den Ruf 'Strippenzieher' beim Wesir.\n\"Der Wesir entrichtet sein höchstes Lob.\"" }
entries[228946] = { ["name"] = "Handwerkstisch im Nest der Weberin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\nErfordert den Ruf 'Kollaborateur' bei der Weberin, dem General oder dem Wesir.\n\"Bringt dies zu Ak'itaz im Nest der Weberin, um einen Handwerkstisch Eurer Wahl herstellen zu lassen.\"" }
entries[228947] = { ["name"] = "Handwerkstisch im Nest der Weberin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhaltet Zugang zu einem Handwerkstisch im Nest der Weberin." }
entries[228948] = { ["name"] = "Jazz' Schrumpfstrahl", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schockt eine Kreatur, um sie zu schwächen und sie um 50% zu schrumpfen! Hält 30 Sek. lang an.\n\nFunktioniert nur in den Glücksmomentminen. (5 Sek. Abklingzeit)\n\"Die Strahlenpistole surrt in Euren Händen. Sie wirkt erstaunlicherweise stabil... und das, obwohl sie nur von rostigen Schrauben und Jazz' Hoffnungen und Träumen zusammengehalten wird.\"" }
entries[228949] = { ["name"] = "Gerüchtekarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (6)\nBenutzen: Deckt den Standort eines Gerüchtes in Azj-Kahet auf Eurer Karte auf.\nErfordert einen aktiven Pakt mit der Weberin, dem General oder dem Wesir.\nErfordert einen aktiven Pakt und den Ruf 'Kumpane'oder höher beim Patron." }
entries[228950] = { ["name"] = "Gerüchtekartenbündel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Deckt den Standort aller aktiven Gerüchte in Azj-Kahet auf.\nErfordert den Ruf 'Kollaborateur' bei der Weberin, dem General oder dem Wesir." }
entries[228951] = { ["name"] = "Paktschatzkarte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt den Standort aller aktiven Paktschätze in Azj-Kahet auf." }
entries[228952] = { ["name"] = "Schatzkartenbündel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Deckt auf, wo sich alle heute verfügbaren Paktschätze befinden.\nErfordert den Ruf 'Mittäter' bei der Weberin, dem General oder dem Wesir." }
entries[228953] = { ["name"] = "Rosafarbene Sprotte", ["text"] = "Verkaufspreis:" }
entries[228954] = { ["name"] = "Wegweiser des Anglers", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch das Aufspüren von Fischen.\nFischschwärme in der Nähe werden auf der Minikarte angezeigt.\nBenötigt Angeln (1)\nVerkaufspreis:" }
entries[228956] = { ["name"] = "Schrotteimer", ["text"] = "Handwerksmaterial\n\"Hat alles, was Ihr braucht! Wird von Händlern verkauft.\"\nVerkaufspreis:" }
entries[228958] = { ["name"] = "Strahlendes Echo", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Erhalten von einem großzügigen Kasten in einer großzügigen Tiefe. Bringt dies zu einer Weltenseelenerinnerung, um die strahlenden Erinnerungen Azeroths zu erleben.\"\nVerkaufspreis:" }
entries[228959] = { ["name"] = "Haufen von unidentifiziertem Fleisch", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Fleisch, der übrig geblieben ist, nachdem Ihr gerade eine Kreatur gehäutet habt. Könnte von dem Wesen selbst stammen oder von dessen letzter Mahlzeit. Es gibt nur einen Weg, das herauszufinden!\"\n<Zum Öffnen rechtsklicken>" }
entries[228963] = { ["name"] = "Unvertrautes Emblem", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Diese Handmarke zeigt ein rotes Emblem, das wie die aufgehende Sonne aussieht und von dem weitreichende Strahlen ausgehen.\"" }
entries[228964] = { ["name"] = "Scharlachroter Siegelring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Ein weiterer Siegelring, dieses Mal von einem Mitglied des Scharlachroten Kreuzzugs. Ein passendes Symbol zu dem des ersten Siegelrings ziert die Innenseite des Bandes.\"" }
