entries[228984] = { ["name"] = "Unverwüstlicher Eisengötze", ["text"] = "The War Within – Saison 1\nWird beim Aufheben gebunden\nBenutzen: Wenn die Gesundheit eines Spielercharakters im Kampf unter 40 % fällt, erwacht der Götze, fügt Gegnern in der Nähe moderaten körperlichen Schaden zu und verspottet sie für 4 Sek. Kann nur alle 2 Min. auftreten.\n\nDiese Kuriosität befindet sich bereits in Eurer Sammlung.\nVerkaufspreis:" }
