entries[228986] = { ["name"] = "Gutscheinheft des Ästhetikers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Von Gaunahs geheimer Sammlung. Diese universell akzeptierten Gutscheine gewähren endlos viele kostenlose Haarschnitte.\"\nVerkaufspreis:" }
entries[228987] = { ["name"] = "Schriftrolle der Teufelsbindung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Opfert die nächste Kreatur, um einen mächtigen Dämon zu beschwören. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[228988] = { ["name"] = "Felsbeleber", ["text"] = "Questgegenstand\nBenutzen: Erweckt die in den ruhelosen Steinen und rastlosen Kieseln in der Nähe verbleibende Energie, sodass sie Euch für kurze Zeit im Kampf unterstützen." }
entries[228989] = { ["name"] = "Zähmlizenz für exotische Kleintiere", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Dokumente, die Eure gesetzliche Berechtigung zur Haltung ungewöhnlicherer Haustiere belegen.\"\nVerkaufspreis:" }
entries[228990] = { ["name"] = "Flasche mit Dampf", ["text"] = "Benutzen: Entfesselt den Dampfdruck. (5 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[228991] = { ["name"] = "Stein der Prophezeiung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Vashti versichert Euch, dass dieser Stein wirklich, WIRKLICH ECHT wichtig für die Zukunft ist.\"" }
entries[228995] = { ["name"] = "Goldener Muffin", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\n\"Ein goldener Götze in Form eines Muffins. Wirkt absolut nutzlos.\"" }
entries[228996] = { ["name"] = "Relikt der Kristallverbindungen", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Teleportiert Euch zum Zielkristall. Funktioniert nur bei Kristallen, die mit dem Relikt abgestimmt sind. (5 Sek. Abklingzeit)" }
