entries[229193] = { ["name"] = "Pheromone der Königin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Pheromone der Königin.\n\nWachen in der Stadt der Fäden stellen sich Euch nicht mehr in den Weg.\n\"Die Pheromone der Königin. Diskret erlangt. Wachen in der Stadt der Fäden können Euch nicht mehr entdecken.\"" }
entries[229194] = { ["name"] = "Pheromone der Königin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Pheromone der Königin.\n\nWachen in der Stadt der Fäden stellen sich Euch nicht mehr in den Weg.\n\"Die Pheromone der Königin. Diskret erlangt. Wachen in der Stadt der Fäden können Euch nicht mehr entdecken.\"" }
entries[229195] = { ["name"] = "Pheromone der Königin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Die Pheromone der Königin.\n\nWachen in der Stadt der Fäden stellen sich Euch nicht mehr in den Weg.\n\"Die Pheromone der Königin. Diskret erlangt. Wachen in der Stadt der Fäden können Euch nicht mehr entdecken.\"" }
entries[229196] = { ["name"] = "Zeichnung eines Bakars", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\n\"Ein aufstrebender Künstler muss das gezeichnet und zurückgelassen haben. Die Zeichnung stellt einen kleinen Bakar dar.\"\nVerkaufspreis:" }
entries[229198] = { ["name"] = "Luft-Ass", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Es zeigt eine Hand, die aus einer Wolke herauskommt und ein von einer Krone umgebenes Schwert ergreift.\"" }
entries[229199] = { ["name"] = "Luft-Zwei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine Person mit verbundenen Augen, die zwei starke Winde auf ihren Schultern balanciert.\"" }
entries[229200] = { ["name"] = "Luft-Drei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt drei stürmische Windböen, die ein Herz durchbohren, mit stürmischen Wolken und Regen dahinter.\"" }
entries[229201] = { ["name"] = "Luft-Vier", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt das Bildnis eines Ritters in der Gebetshaltung, in voller Länge, vermutlich auf seinem Grabmal.\"" }
entries[229202] = { ["name"] = "Luft-Fünf", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt einen Mann, der verächtlich auf zwei zurückweichende und niedergeschlagene Gestalten herabblickt, die ihre Luftsäcke auf dem Boden liegen gelassen haben. Zwei weitere trägt er auf seiner linken Schulter, einen dritten hält er in der rechten Hand.\"" }
entries[229203] = { ["name"] = "Luft-Sechs", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt einen Fergen, der Passagiere in seinem Boot zum anderen Ufer bringt. Der Kurs ist ruhig, und da die Fracht leicht ist, kann man sehen, dass die Arbeit nicht überfordernd ist.\"" }
entries[229204] = { ["name"] = "Luft-Sieben", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine Person, die dabei ist, fünf Winde schnell wegzutragen. Zwei andere Winde liegen auf dem Boden und ein Lager ist in der Nähe.\"" }
entries[229205] = { ["name"] = "Luft-Acht", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt einen gefesselten Gefangenen mit verbundenen Augen, der von acht stürmischen Winden umgeben ist. Es handelt sich jedoch eher um vorübergehende Fesseln als um eine unwiderrufliche Knechtschaft.\"" }
entries[229206] = { ["name"] = "Feuer-Ass", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Es zeigt eine Hand, die aus einem brennenden Feuerball herauskommt und einen von Rauch umhüllten Zauberstab hält.\"" }
entries[229207] = { ["name"] = "Feuer-Zwei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine hochgewachsene Gestalt, die von einem Zinnendach aus über das Meer und die Küste blickt. In der rechten Hand hält sie eine Kugel und in der linken einen brennenden Stab, den sie auf der Zinne abstützt. Ein weiterer brennender Stab ist in einem Ring rechts von der Figur angebracht.\"" }
entries[229208] = { ["name"] = "Feuer-Drei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine ruhige, stattliche Gestalt von hinten, die von einer Klippe aus auf die über das Meer fahrenden Schiffe blickt. Drei Stäbe sind im Boden verankert, jeder mit einer Laterne, und die Figur lehnt sich leicht auf einen der Stäbe.\"" }
entries[229209] = { ["name"] = "Feuer-Vier", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt vier große Säulen im Vordergrund, zwischen denen eine große Girlande aus reinsten Flammen hängt. Zwei Figuren halten duftende Blumen hoch, und neben ihnen führt eine Brücke über einen Wassergraben zu einem alten Herrenhaus.\"" }
entries[229210] = { ["name"] = "Feuer-Fünf", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine Gruppe junger Leute, die ihre Stöcke wie beim Sport schwingen. Sie führen einen Scheinkrieg, und ihre Augen brennen wie Feuer.\"" }
entries[229211] = { ["name"] = "Feuer-Sechs", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine Figur auf einem Pferd, die mit einer Lorbeerkrone geschmückt ist und ein Flammenschwert führt. Sechs Lakaien mit ähnlichen Flammenschwertern stehen neben der Figur.\"" }
entries[229212] = { ["name"] = "Feuer-Sieben", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine entschlossene Gestalt, die hoch oben auf einem zerklüfteten Hügel steht und eine Fackel hält. Sieben weitere Fackeln werden von unten auf sie gerichtet.\"" }
entries[229213] = { ["name"] = "Feuer-Acht", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt acht flammende Pfeile, die über den Himmel fliegen und sich dem Ende ihrer Bahn nähern. Das, wofür sie stehen, rückt in greifbare Nähe - vielleicht steht es sogar schon vor der Tür.\"" }
entries[229214] = { ["name"] = "Frost-Ass", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Es zeigt eine Hand, die aus dem frisch gefallenen Schnee herauskommt und den Schaft eines mit dampfendem Wasser gefüllten Kelches umklammert.\"" }
entries[229215] = { ["name"] = "Frost-Zwei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt zwei junge Leute, die in einer Winterlandschaft stehen und sich mit Fahnen aus reinstem Eis gegenseitig anstoßen.\"" }
entries[229216] = { ["name"] = "Frost-Drei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt Feiernde, die mit erhobenen Bechern in einem Garten tanzen, als würden sie sich gegenseitig etwas versprechen. Sanfter Schnee fällt um sie herum.\"" }
entries[229217] = { ["name"] = "Frost-Vier", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine in Pelze gehüllte Gestalt, die unter einer Tanne sitzt und drei Kelche betrachtet, die vor ihr im Schnee liegen. Ein Arm, der aus einer Wolke herausragt, bietet der Figur einen vierten Kelch an. Ihr Gesichtsausdruck verrät Unzufriedenheit.\"" }
entries[229218] = { ["name"] = "Frost-Fünf", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine dunkle, verhüllte Gestalt, die von der Seite auf drei liegende Becher blickt, die in Wasserbecken ruhen. Zwei weitere Becher stehen hinter der Figur auf Sockeln aus Eis. Im Hintergrund führt eine Brücke zu einem kleinen Bergfried.\"" }
entries[229219] = { ["name"] = "Frost-Sechs", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt Kinder in einem alten Garten, die mit Bechern voller schmelzendem Schnee Blumen gießen.\"" }
entries[229220] = { ["name"] = "Frost-Sieben", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt seltsame Visionen, die sich aus sieben Kelchen aus reinstem Eis ergießen. Aber diese Bilder sind die eines fantastischen Geistes.\"" }
entries[229221] = { ["name"] = "Frost-Acht", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine niedergeschlagene Figur, die weggeht und die Schalen ihres Glücks, ihres Unternehmens, ihrer Unternehmung oder ihres früheren Anliegens zurücklässt, um vom eindringenden Eis verschlungen zu werden.\"" }
entries[229222] = { ["name"] = "Erd-Ass", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Es zeigt eine Hand, die aus dem felsigen Boden in einer Staubwolke herauskommt und eine Steinscheibe hochhält.\"" }
entries[229223] = { ["name"] = "Erd-Zwei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt ein Kind, das mit einer Steinscheibe in jeder Hand tanzt. Die Scheiben sind durch die endlose Schnur verbunden, die wie die umgekehrte Zahl 8 aussieht.\"" }
entries[229224] = { ["name"] = "Erd-Drei", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt einen Bildhauer bei der Arbeit in einem Kloster. Der Lehrling hat seine Belohnung erhalten und ist nun ernsthaft an der Arbeit.\"" }
entries[229225] = { ["name"] = "Erd-Vier", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine gekrönte Gestalt mit einer Steinscheibe über dem Kopf, die mit Händen und Armen eine weitere Scheibe umklammert und zwei weitere Scheiben unter den Füßen hat. Sie hält an dem fest, was sie hat.\"" }
entries[229226] = { ["name"] = "Erd-Fünf", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt zwei Bettler in einem Staubsturm, die an einem Fenster vorbeigehen, das von fünf glühenden Steinscheiben erleuchtet wird.\"" }
entries[229227] = { ["name"] = "Erd-Sechs", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine Person in der Kluft eines Händlers, die Geld auf einer Waage abwiegt und an die Bedürftigen und Notleidenden verteilt. Es ist ein Zeugnis vom Erfolg im Leben, aber auch der Herzensgüte.\"" }
entries[229228] = { ["name"] = "Erd-Sieben", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt eine junge Person, die sich auf ihren Stab lehnt und sieben steinerne Scheiben betrachtet, die an einem Haufen Grün zu ihrer Rechten hängen. Man könnte sagen, dass es sich um Schätze handelt, an dem ihr Herz hängt.\"" }
entries[229229] = { ["name"] = "Erd-Acht", ["text"] = "Fortunakartenset des Dunkelmond-Jahrmarkts\n\"Sie zeigt einen Künstler in Gestein bei der Arbeit, die er in Form von Trophäen ausstellt.\"" }
