entries[229348] = { ["name"] = "Schlüssel für Incognitro, das Unentzifferbare Teufelsrad", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Incognitro, das Unentzifferbare Teufelsrad, beschwört.\nBeschwört ein dämonisch angetriebenes Gefährt oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese experimentelle dämonische Maschine wurde von Chefingenieur Ulzik entwickelt, um dimensionsübergreifende Reisen zu ermöglichen. Trotz mehrerer Todesfälle während der Testläufe war Ulzik davon überzeugt, dass das Vehikel die zuvor unergründlichen Geheimnisse des Universums offenbaren würde.\"\nWeltereignis:\nDer 20. Geburtstag von WoW?" }
entries[229350] = { ["name"] = "Kauspielzeug", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig" }
entries[229351] = { ["name"] = "Spirituelles Räucherwerk", ["text"] = "Geheimnisse von Azeroth\nWird beim Aufheben gebunden\nBenutzen: Beschwört eine spirituelle Verbindung zu Maru der Juniorschnüfflerin. Maru kann Hinweise auf Geheimnisse von Azeroth geben.\n\"Eine Schüssel mit aromatischem Ambra, das gesegnet wurde, um Oacha'noa zu ehren.\"\nVerkaufspreis:" }
entries[229353] = { ["name"] = "Wutentbrannter Götze", ["text"] = "Wird beim Aufheben gebunden" }
entries[229354] = { ["name"] = "Truhe eines Algariabenteurers", ["text"] = "Wird beim Aufheben gebunden\n\"Wöchentliche Truhe mit Stufenaufstiegs-Ausrüstung, Gold und mehr.\"\n<Zum Öffnen rechtsklicken>" }
entries[229355] = { ["name"] = "Chromies wertvolle Wundertüte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Gold, Tapferkeitssteine, eine Chance auf Wappen und einen bis zum Ausrüsten kriegsmeutengebundenen Gegenstand.\"\n<Zum Öffnen rechtsklicken>" }
entries[229358] = { ["name"] = "Miniaturboot der Tuskarr", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Das muss Maru gehören.\"" }
entries[229359] = { ["name"] = "Chromies Wundertüte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält einen Gegenstand für Eure Stufe und Klasse, der bis zum Ausrüsten kriegsmeutengebunden ist.\"\n<Zum Öffnen rechtsklicken>" }
entries[229361] = { ["name"] = "Xal'atath, Klinge des Schwarzen Imperiums", ["text"] = "Questgegenstand\nEinzigartig\n\"Xal'atath hat ihren eigenen Kopf. Ignoriert ihr unerträgliches Flüstern. Glaubt niemals ihren Lügen. Nehmt, was Ihr von ihr braucht, aber denkt immer daran, dass die dunkle Präsenz in der Klinge nicht Eure Verbündete ist.\"" }
entries[229363] = { ["name"] = "Zaranitknospe", ["text"] = "Questgegenstand\n\"Die Knospe einer Zaranitblume. Von einer Pflanze, die sorgfältig in der intakten Biokuppel auf K'aresh gezüchtet wurde.\"" }
entries[229364] = { ["name"] = "Wappen der Geißel", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[229365] = { ["name"] = "Singender Rohcitrin", ["text"] = "Wird beim Aufheben gebunden\n\"Ihr hört einen betörenden Gesang, während er sich regungslos in Eurem Inventar befindet. Der Gesang wird vor Verlegenheit zu einer flüsternden Stimme, wenn Ihr ihn an Euer Ohr haltet.\"\nVerkaufspreis:" }
entries[229366] = { ["name"] = "Brrrgl", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick Brrrrgl beschwören oder wieder freigeben.\n80 ( 80)" }
