entries[229388] = { ["name"] = "Wappenbuch des geachteten Kämpfers", ["text"] = "The War Within – Saison 2\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Zertifiziert hergestellte Ausrüstung für PvP-Schlachtfelder und erlaubt Skalierung auf Ggst. 658.\n\nHerstellungsverfahren benötigen mehrere.\n\"Erhältlich durch PvP-Aktivitäten und für Ehrenpunkte bei PvP-Rüstmeistern in Dornogal. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[229389] = { ["name"] = "Wappenbuch des geachteten Aspiranten", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+50 Rezeptschwierigkeit\nGewährt die folgende Eigenschaft: Zertifiziert hergestellte Ausrüstung für PvP-Schlachtfelder und erlaubt Skalierung auf Ggst. 671.\n\nHerstellungsverfahren benötigen mehrere.\n\"Erhältlich für Ehrenpunkte bei PvP-Rüstmeistern in Dornogal.\"" }
entries[229390] = { ["name"] = "Wappenbuch des geachteten Gladiators", ["text"] = "The War Within – Saison 2\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+150 Rezeptschwierigkeit\nGewährt die folgende Eigenschaft: Zertifiziert hergestellte Ausrüstung für PvP-Schlachtfelder und erlaubt Skalierung auf Ggst. 684.\n\nHerstellungsverfahren benötigen mehrere.\n\"Erhältlich für Eroberungspunkte bei PvP-Rüstmeistern in Dornogal.\"" }
entries[229392] = { ["name"] = "Zerknüllter Lieferschein", ["text"] = "Questgegenstand\n80 ( 80)\n\"Ein Schreiben an die Tiefenreiterbande, in der Zahlungen in Form von Waffen aufgeführt sind.\"" }
entries[229401] = { ["name"] = "Pamphlet des Handwerkerkonsortiums", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Eine besondere Notiz für eifrige Wettstreiter aller Ränge!\"" }
entries[229405] = { ["name"] = "Entropischer Kern", ["text"] = "Questgegenstand\n\"Kondensierte Energien, die dem Boden von K'aresh entnommen wurden.\"" }
entries[229407] = { ["name"] = "Zitrussäure", ["text"] = "Questgegenstand\n\"Ob das den Geschmack von Grog verbessert, steht zur Debatte.\"" }
entries[229408] = { ["name"] = "Verbrannte Feder", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Die Feder weist Spuren von Kämpfen und Verbrennungen auf. Außerdem ist sie an manchen Stellen gerissen und eine merkwürdige grüne Flüssigkeit tropft von einem Ende herab.\"" }
entries[229409] = { ["name"] = "Ausgezupfte Feder", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Die Feder scheint absichtlich ausgezupft worden zu sein, sodass nun genau 48 Seitenäste auf der linken Seite fehlen und 93 Seitenäste auf der rechten Seite verbleiben.\"" }
entries[229410] = { ["name"] = "Gefrorene Feder", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Die Feder ist gefroren und hat eine merkwürdige Kombination an Gerüchen an sich: Vulkanasche, Salzwasser und Maschinenöl.\"" }
entries[229411] = { ["name"] = "Normale Feder", ["text"] = "Geheimnisse von Azeroth\nQuestgegenstand\nEinzigartig\n\"Diese Feder scheint unverändert zu sein, wie man es zu Beginn einer Reise erwarten würde.\"" }
entries[229413] = { ["name"] = "\"Dogg-Saron\"-Kostüm", ["text"] = "Benutzen: Putzt Euren mopsigen Streuner heraus.\n\"Neu beschriftetes Imitat eines alten Schlotternachtkostüms.\"\nVerkaufspreis:" }
entries[229414] = { ["name"] = "Moira Thaurissans Hammer", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\nVerkaufspreis:" }
entries[229418] = { ["name"] = "Zügel des goldgeschmückten Händlerbrutosaurus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier für 3 Personen mit Händlern beschwört.\nBeschwört Euren goldgeschmückten Händlerbrutosaurus oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Morten und Killia war nie bewusst, wie lukrativ ihre neue fraktionsübergreifende Handelspartnerschaft sein würde. Zumindest bis zu dem Tag, an dem sie sich endlich dieses schöne Geschöpf kaufen konnten, um ihnen ihre Reisen zu erleichtern. Und selbstverständlich in strahlend goldenem Stil.\"\nWoW-Shop" }
entries[229419] = { ["name"] = "Fassgrundurkunde", ["text"] = "Questgegenstand\n80 ( 80)\n\"Die Urkunde für die Fassgrund-Apartments. Moz wird das nicht mehr brauchen.\"" }
entries[229420] = { ["name"] = "Animakugel", ["text"] = "Questgegenstand\nBenutzen: Wirft Eurem freundlichen Tier einen Ball zu.\n\"Ein Animaball mit einer griffigen Oberfläche. Wenn Ihr ihn werft, quietscht er. Tiere scheinen ihn zu lieben.\"" }
entries[229422] = { ["name"] = "Truhe mit Lorenhallausrüstung", ["text"] = "The War Within – Saison 2\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft einen seelengebundenen Dungeongegenstand, der in Saison 2 von The War Within für Eure Beutespezialisierung nützlich ist." }
entries[229423] = { ["name"] = "Echovermesser", ["text"] = "Questgegenstand\n\"Eine Miniaturversion der Technologie des Kartells Om.\"" }
entries[229424] = { ["name"] = "Animasauger", ["text"] = "Questgegenstand\nBenutzen: Saugt Kleintiere, Taugenichtse und (mutmaßlich) kosmische Wesen in der Nähe auf.\n\nKann beim Zaubern laufen. (3 Sek. Abklingzeit)\n\"Anscheinend gibt es im hinteren Bereich ein Portal, das direkt nach K'aresh führt. Man hat Euch versichert, dass es sicher ist. Wahrscheinlich.\"" }
entries[229425] = { ["name"] = "Streitkolben der Bronzebarts", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nEinhändig Streitkolben\n1 Schaden Geschwindigkeit 2.60\n(0.4 Schaden pro Sekunde)\n\"Für die Könige von Eisenschmiede geschmiedet, ist dieser Streitkolben auf ewig an die Erblinie der Bronzebärte gebunden.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[229426] = { ["name"] = "Uralter Langbogen der Amani", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\n\"Mit Tarnfleck, der auf die dunklen Pinienbäume Zul'Amans abgestimmt wurde.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
